CREATE TABLE IF NOT EXISTS inv_transfers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transfer_ref VARCHAR(80) NOT NULL UNIQUE, transfer_date DATE NOT NULL, source_branch_id INT UNSIGNED NOT NULL, source_warehouse_id INT UNSIGNED NOT NULL, destination_branch_id INT UNSIGNED NOT NULL, destination_warehouse_id INT UNSIGNED NOT NULL, note VARCHAR(255) NULL, status ENUM('DRAFT','SENT','RECEIVED','CANCELLED') NOT NULL DEFAULT 'DRAFT', created_by INT UNSIGNED NOT NULL, sent_by INT UNSIGNED NULL, sent_at DATETIME NULL, received_by INT UNSIGNED NULL, received_at DATETIME NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_inv_transfer_sb FOREIGN KEY(source_branch_id) REFERENCES branches(id), CONSTRAINT fk_inv_transfer_db FOREIGN KEY(destination_branch_id) REFERENCES branches(id), CONSTRAINT fk_inv_transfer_sw FOREIGN KEY(source_warehouse_id) REFERENCES inv_warehouses(id), CONSTRAINT fk_inv_transfer_dw FOREIGN KEY(destination_warehouse_id) REFERENCES inv_warehouses(id), KEY ix_inv_transfer_status(status,transfer_date));
CREATE TABLE IF NOT EXISTS inv_transfer_lines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transfer_id INT UNSIGNED NOT NULL, item_id INT UNSIGNED NOT NULL, quantity DECIMAL(18,3) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_inv_transfer_line_h FOREIGN KEY(transfer_id) REFERENCES inv_transfers(id) ON DELETE CASCADE, CONSTRAINT fk_inv_transfer_line_i FOREIGN KEY(item_id) REFERENCES md_items(id), CHECK(quantity>0));
INSERT IGNORE INTO permissions(code,name) VALUES ('inventory.transfer.view','Lihat transfer gudang'),('inventory.transfer.create','Buat transfer gudang'),('inventory.transfer.send','Kirim transfer gudang'),('inventory.transfer.receive','Terima transfer gudang');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code='inventory.transfer.view' WHERE r.name IN ('Owner','Finance');
